import{_ as i}from"./plugin-vue_export-helper-c27b6911.js";import{r as t,o as c,c as d,d as s,e as n,b as e,w as l,a as r,f as o}from"./app-8b917aed.js";const u={},k=s("p",null,[n("最近在折腾一件事：让一台 Linux 上的 DeepSeek Harness（下称 dsh）和一台 Windows 上的 dsh 互相通信——不是 SSH 上去跑命令，而是"),s("strong",null,"让两个 agent 互相派活、互相插话"),n("。最后做出来的是一个叫 "),s("code",null,"dsh-peer"),n(" 的插件，加上一个能看到对端思考过程的活动看板。")],-1),v={href:"https://github.com/SparksDing/dsh-peer",target:"_blank",rel:"noopener noreferrer"},h=o(`<h2 id="_1-背景与约束" tabindex="-1"><a class="header-anchor" href="#_1-背景与约束" aria-hidden="true">#</a> 1. 背景与约束</h2><p>dsh 自带的 SDK 协议只走 stdio：父进程 spawn 一个 <code>dsh --profile sdk</code> 子进程，通过标准输入输出说 JSON-RPC。跨机器没有任何现成通道。</p><p>现实约束有三条：</p><ol><li><strong>Windows 在内网</strong>，只能主动往外连，不能接受入站连接。</li><li><strong>Linux 的入站端口被安全组挡住</strong>，只有 80/3080 这类 HTTP 端口可达。</li><li>被驱动的不是裸工具进程，而是一个<strong>完整 runtime</strong>：有自己的模型路由、工具集、会话持久化和文件系统。</li></ol><p>所以设计目标很明确：在不改动 dsh 核心的前提下，复用它的 SDK 协议，补一层&quot;跨机器连接 + 对等双向&quot;。</p><h2 id="_2-架构-连接方向与服务方向相反" tabindex="-1"><a class="header-anchor" href="#_2-架构-连接方向与服务方向相反" aria-hidden="true">#</a> 2. 架构：连接方向与服务方向相反</h2><p>这是整个设计里最容易绕晕、也最关键的一点：</p><table><thead><tr><th></th><th>建立连接</th><th>发 harness 请求</th><th>响应</th></tr></thead><tbody><tr><td>hub（公网侧）</td><td>监听</td><td>发 <code>session/prompt</code></td><td>只响应 <code>peer/reply</code></td></tr><tr><td>link（内网侧）</td><td>拨号</td><td>不发</td><td>响应 harness 方法</td></tr></tbody></table><p>NAT 只允许内网机器主动出站，所以必须让 Windows 当&quot;连接的客户端&quot;；但它同时是&quot;能力的服务端&quot;——把本机 agent 服务给 hub 用。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>        公网侧 (hub)                              内网侧 (link)
  ┌──────────────────────┐                  ┌──────────────────────┐
  │ peer_ask / peer_send │  JSON-RPC 请求   │  HarnessSdkJsonRpc   │
  │ peer_wait / peer_inbox│ ───────────────► │  Server              │
  │                      │                  │   ├─ agents.create   │
  │  PeerHub             │ ◄─────────────── │   ├─ preset.mount    │
  │  链接注册 · 会话状态   │  session.event   │   └─ followup()      │
  └──────────────────────┘                  └──────────────────────┘
            │                                          ▲
            └──────── TCP / TLS / WebSocket ───────────┘
                       （由 link 主动拨号）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>分层也很直接：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>模型
 │  peer_ask / peer_send / peer_wait / peer_inbox        (lib/tools.js)
 ▼
PeerHub  链接注册表 · 会话状态 · 收件箱 · 超时          (lib/hub.js)
 │
PeerConnection  JSON-RPC 请求/响应 · 心跳 · 超时 · 关闭  (lib/protocol.js)
 │
LineTransport   换行分隔 JSON-RPC 2.0 帧               (lib/transport.js)
 │
Duplex:  TCP / TLS / WebSocket                          (lib/ws.js)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-协议-复用-sdk-方言-不另造-agent-api" tabindex="-1"><a class="header-anchor" href="#_3-协议-复用-sdk-方言-不另造-agent-api" aria-hidden="true">#</a> 3. 协议：复用 SDK 方言，不另造 agent API</h2><h3 id="_3-1-帧与传输" tabindex="-1"><a class="header-anchor" href="#_3-1-帧与传输" aria-hidden="true">#</a> 3.1 帧与传输</h3><p>每一个帧就是一行 JSON-RPC 2.0：带 <code>method</code> 和 <code>id</code> 是请求，只有 <code>id</code> 是响应，只有 <code>method</code> 是通知。和 <code>@deepseek-ai/dsh-sdk-protocol</code> 完全一致，所以链路两端天然能说同一套 harness 方法：</p><ul><li><code>initialize</code>：确定 cwd、provider、model</li><li><code>session/prompt</code>：投递一条用户消息</li><li><code>session/wait</code>、<code>session/working-directory/*</code></li><li>通知：<code>session.event</code>、<code>session.status</code></li></ul><p>自定义的只有四个：<code>peer/hello</code>、<code>peer/ping</code>、<code>peer/info</code>、<code>peer/reply</code>，以及一个兼容用的 <code>peer/ensure-session</code>。</p><p>传输是可插拔的，因为同一条 JSON-RPC 只要落在 <code>Duplex</code> 上就行：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// lib/protocol.js</span>
<span class="token keyword">this</span><span class="token punctuation">.</span>#transport <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">LineTransport</span><span class="token punctuation">(</span>socket<span class="token punctuation">,</span> socket<span class="token punctuation">)</span>
socket<span class="token punctuation">.</span>setNoDelay<span class="token operator">?.</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span>
socket<span class="token punctuation">.</span>setKeepAlive<span class="token operator">?.</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token number">15_000</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-握手" tabindex="-1"><a class="header-anchor" href="#_3-2-握手" aria-hidden="true">#</a> 3.2 握手</h3><p>link 连上后发的第一个请求是：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;jsonrpc&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2.0&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;req_...&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;method&quot;</span><span class="token operator">:</span> <span class="token string">&quot;peer/hello&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;params&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>
    <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;windows-pc&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;role&quot;</span><span class="token operator">:</span> <span class="token string">&quot;link&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;token&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&lt;共享密钥&gt;&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;platform&quot;</span><span class="token operator">:</span> <span class="token string">&quot;win32&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;cwd&quot;</span><span class="token operator">:</span> <span class="token string">&quot;C:\\\\Users\\\\admin&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;provider&quot;</span><span class="token operator">:</span> <span class="token string">&quot;deepseek-official&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;model&quot;</span><span class="token operator">:</span> <span class="token string">&quot;deepseek-v4-flash&quot;</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>hub 校验协议版本与 token（常量时间比较），拒绝不匹配的连接。之后每条连接上：</p><ul><li>应用层 <code>peer/ping</code> 每 25 秒一次，连续两次失败就断开；</li><li>断线后 link 指数退避重连，1s 起步、30s 封顶。</li></ul><h3 id="_3-3-一次-peer-ask-的完整时序" tabindex="-1"><a class="header-anchor" href="#_3-3-一次-peer-ask-的完整时序" aria-hidden="true">#</a> 3.3 一次 <code>peer_ask</code> 的完整时序</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>我: peer_ask(peer=&quot;HP&quot;, prompt=&quot;查磁盘&quot;)
 │
 ├─ hub.require(&quot;HP&quot;)                     按名字/唯一子串找 link
 ├─ sessionId = peer-HP-default           会话身份 = 链接名 + 话题名
 ├─ initialize {cwd, provider, model}     每条连接只做一次
 ├─ peer/ensure-session {sessionId}       link 尝试 resume 历史，没有就等 prompt 建
 ├─ session/prompt {sessionId, blocks} ──► link
 │                                          └─ PeerHarnessServer
 │                                             ├─ agentPresets.resolve(&quot;standard&quot;)
 │                                             ├─ agents.create/resume
 │                                             │   setup: preset.mount(agentCtx)
 │                                             └─ agent.followup(userMessage)
 │                                                ↓ 真实模型 + 真实工具跑一轮
 │                                          ◄── session.event  (逐条流式)
 │                                          ◄── session.status (running/idle)
 ├─ hub 收到 agent/inbox/spliced          确认消息已入队（关联 messageId）
 ├─ hub 等到 idle 且 idleCount 递增        判定这一轮结束
 └─ 返回最后一条 assistant/message 的文本
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里有个不太直观的实现细节：<strong>hub 不是靠 <code>session/wait</code> 判断回合结束的</strong>。原因是 0.2.0 版本的 SDK server 根本没有 <code>session/wait</code>，只有 <code>initialize</code> / <code>session/prompt</code> / <code>shutdown</code>。所以 hub 自己在每条连接上维护每个会话的：</p><ul><li><code>receipts</code>：哪些 messageId 已经被 <code>agent/inbox/spliced</code> 确认</li><li><code>idleCount</code>：<code>session.status</code> 变成 idle 的次数</li><li><code>lastAssistant</code>：最后一条助手消息的文本</li></ul><p>等待条件写成&quot;idleCount 相比投递前递增&quot;，而不是&quot;等一个 idle 通知&quot;——后者会在&quot;回合已经在等待开始前结束&quot;时丢事件。</p><h3 id="_3-4-会话身份与续接" tabindex="-1"><a class="header-anchor" href="#_3-4-会话身份与续接" aria-hidden="true">#</a> 3.4 会话身份与续接</h3><p>会话 id 是 <code>peer-&lt;link&gt;-&lt;topic&gt;</code>：</p><ul><li>同一个 <code>session</code> 名字复用同一条对话，<code>fresh: true</code> 另起一条；</li><li>重连后 hub 重新 <code>initialize</code>，再对旧会话发 <code>peer/ensure-session</code>；</li><li>link 侧先尝试 <code>session/resume</code> 载入持久化历史，失败（首次使用没有历史）就等 <code>session/prompt</code> 创建。</li></ul><p>这样即使 hub 或 link 重启，对话也能接上。</p><h3 id="_3-5-事件过滤" tabindex="-1"><a class="header-anchor" href="#_3-5-事件过滤" aria-hidden="true">#</a> 3.5 事件过滤</h3><p><code>HarnessSdkJsonRpcServer</code> 会把<strong>本机所有会话</strong>的 <code>session.event</code> 都广播给 transport。对 peer 通道来说这既浪费又泄露隐私，所以 link 侧包了一层过滤 transport：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token function">notify</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;session.event&#39;</span> <span class="token operator">||</span> method <span class="token operator">===</span> <span class="token string">&#39;session.status&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>owned<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>sessionId<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span>
  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;subagent.started&#39;</span> <span class="token operator">||</span> method <span class="token operator">===</span> <span class="token string">&#39;subagent.finished&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>owned<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>parentSessionId<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span>
  <span class="token punctuation">}</span>
  conn<span class="token punctuation">.</span><span class="token function">notify</span><span class="token punctuation">(</span>method<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>owned</code> 在收到 <code>session/prompt</code> / <code>session/resume</code> 时登记，只包含这条 peer 连接自己创建的会话。</p><h2 id="_4-后端实现里的几个关键点" tabindex="-1"><a class="header-anchor" href="#_4-后端实现里的几个关键点" aria-hidden="true">#</a> 4. 后端实现里的几个关键点</h2><h3 id="_4-1-工具是-preset-组成的-不是全局的" tabindex="-1"><a class="header-anchor" href="#_4-1-工具是-preset-组成的-不是全局的" aria-hidden="true">#</a> 4.1 工具是 preset 组成的，不是全局的</h3><p>把 link 装进 <code>web</code> profile 时会遇到一个坑：peer 会话的 agent 只拿到全局注册的工具（<code>peer_reply</code>、<code>peer_status</code>），没有 <code>bash</code>、<code>read</code>、<code>write</code>——因为 Web profile 把模型可见的工具行都移进了 agent preset。</p><p>解法是继承 <code>HarnessSdkJsonRpcServer</code>，覆写 <code>createSession</code>，在 agent 发布前的 <code>setup</code> 里挂载 preset：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> preset <span class="token operator">=</span> <span class="token keyword">await</span> presets<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>presetId<span class="token punctuation">)</span>   <span class="token comment">// 默认取 registry 的 default</span>
<span class="token function-variable function">setup</span> <span class="token operator">=</span> <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token parameter">agentCtx</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">await</span> presets<span class="token punctuation">.</span><span class="token function">mount</span><span class="token punctuation">(</span>agentCtx<span class="token punctuation">,</span> preset<span class="token punctuation">.</span>id<span class="token punctuation">)</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> handle <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>ctx<span class="token punctuation">.</span>agents<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
  sessionId<span class="token punctuation">,</span>
  <span class="token literal-property property">meta</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">cwd</span><span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>cwd<span class="token punctuation">,</span> <span class="token literal-property property">agentPreset</span><span class="token operator">:</span> preset<span class="token punctuation">.</span>id <span class="token punctuation">}</span><span class="token punctuation">,</span>
  agentOptions<span class="token punctuation">,</span>
  setup<span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>setup</code> 是 dsh 文档里的创建钩子：它在 agent 真正发布之前执行，所以 preset 里的工具在第一次组装 prompt 时就已存在。</p><h3 id="_4-2-旧版本没有-session-resume" tabindex="-1"><a class="header-anchor" href="#_4-2-旧版本没有-session-resume" aria-hidden="true">#</a> 4.2 旧版本没有 <code>session/resume</code></h3><p>0.2.0 的 SDK server 只有三个方法，重连后对已存在的 session id 调 <code>agents.create</code> 会报 <code>session &quot;...&quot; already exists</code>。兼容做法是捕获这个错误回退到 <code>agents.resume</code>：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">try</span> <span class="token punctuation">{</span>
  handle <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>ctx<span class="token punctuation">.</span>agents<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">{</span> sessionId<span class="token punctuation">,</span> meta<span class="token punctuation">,</span> agentOptions<span class="token punctuation">,</span> setup <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>error<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">already exists</span><span class="token regex-delimiter">/</span><span class="token regex-flags">i</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>error<span class="token punctuation">.</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">throw</span> error
  handle <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>ctx<span class="token punctuation">.</span>agents<span class="token punctuation">.</span><span class="token function">resume</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">resumeSessionId</span><span class="token operator">:</span> sessionId<span class="token punctuation">,</span> agentOptions<span class="token punctuation">,</span> setup <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-只有-http-端口可达时-用-websocket-桥" tabindex="-1"><a class="header-anchor" href="#_4-3-只有-http-端口可达时-用-websocket-桥" aria-hidden="true">#</a> 4.3 只有 HTTP 端口可达时，用 WebSocket + 桥</h3><p>公网侧 3099 被安全组挡住，但 3080 通（nginx）。于是加了一条路径：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>link --ws--&gt; nginx (/dsh-peer) --ws--&gt; peer-ws-bridge --tcp--&gt; hub:3099
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>桥本身很小：接受 WebSocket 升级，把每个连接 <code>pipe</code> 到 hub 的 TCP 端口。这样 hub 完全不用改，仍然只监听原始 TCP。</p><p>nginx 侧只需要一条精确匹配的路径，不影响 dsh 自己的 GUI：</p><div class="language-nginx line-numbers-mode" data-ext="nginx"><pre class="language-nginx"><code><span class="token directive"><span class="token keyword">location</span> = /dsh-peer</span> <span class="token punctuation">{</span>
    <span class="token directive"><span class="token keyword">proxy_pass</span> http://127.0.0.1:3098</span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">proxy_http_version</span> 1.1</span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">proxy_set_header</span> Upgrade <span class="token variable">$http_upgrade</span></span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">proxy_set_header</span> Connection <span class="token string">&quot;upgrade&quot;</span></span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">proxy_read_timeout</span> <span class="token number">86400s</span></span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-4-二进制走独立上传口" tabindex="-1"><a class="header-anchor" href="#_4-4-二进制走独立上传口" aria-hidden="true">#</a> 4.4 二进制走独立上传口</h3><p>协议只传 JSON 文本。截图、预览二维码这类二进制如果塞进 JSON-RPC（base64）既贵又脆，所以另开了一个带 token 的 HTTP 上传口：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>PUT http://hub:3080/peer-files/upload/shot1.png?token=...
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>对面用 <code>Invoke-WebRequest -Method Put -InFile</code> 一推就完事。</p><h2 id="_5-前端-活动看板" tabindex="-1"><a class="header-anchor" href="#_5-前端-活动看板" aria-hidden="true">#</a> 5. 前端：活动看板</h2><h3 id="_5-1-为什么做在-桥-上" tabindex="-1"><a class="header-anchor" href="#_5-1-为什么做在-桥-上" aria-hidden="true">#</a> 5.1 为什么做在&quot;桥&quot;上</h3><p>需求是能看到对端的<strong>思考过程</strong>和细节：用户消息、reasoning、助手文本、工具调用与结果、回合边界、状态变化。</p><p>最直接的想法是做成 dsh 的客户端 UI 插件，但有两个问题：</p><ol><li>客户端插件的数据面要走 typert 的 Remote 描述符，而描述符是<strong>构建期生成</strong>的，出树插件很难接；</li><li>更关键的是——不想为了加一个只读面板去重启正在运行的 hub。</li></ol><p>而 WebSocket 桥正好夹在 link 和 hub 之间，<strong>能看到全部 JSON-RPC 帧</strong>。于是换个思路：桥旁路解析帧，喂一个内存事件存储，再吐一个极简的 HTTP 看板。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>link --ws--&gt; nginx(/dsh-peer) --&gt; 桥 --tcp--&gt; hub(3099)
                                  │
                                  ├─ 解析 session.event / session.status
                                  └─ nginx(/peer-ui/) --&gt; GET / 与 GET /api/activity
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>hub 和 link 一行都不用改。</p><h3 id="_5-2-事件模型" tabindex="-1"><a class="header-anchor" href="#_5-2-事件模型" aria-hidden="true">#</a> 5.2 事件模型</h3><p>dsh 的会话事件是带 <code>type</code> 的判别联合。看板只挑有展示价值的几类：</p><table><thead><tr><th>事件</th><th>展示</th></tr></thead><tbody><tr><td><code>user/message</code></td><td>用户/系统注入的消息文本</td></tr><tr><td><code>assistant/message</code></td><td>拆成 <code>reasoning</code> 与 <code>text</code> 两段（content block 里分别是 两个 type）</td></tr><tr><td><code>tool/call</code></td><td>工具名 + 参数 JSON</td></tr><tr><td><code>tool/result</code></td><td>结果文本，<code>isError</code> 时标红</td></tr><tr><td><code>turn/start</code> / <code>turn/end</code></td><td>回合边界与结束原因</td></tr><tr><td><code>session.status</code></td><td>running / idle</td></tr></tbody></table><p>每条事件压成一个扁平结构，进环形缓冲：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token punctuation">{</span> seq<span class="token punctuation">,</span> at<span class="token punctuation">,</span> kind<span class="token punctuation">,</span> title<span class="token operator">?</span><span class="token punctuation">,</span> text<span class="token operator">?</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>seq</code> 是全局单调递增的，正好用来做增量拉取。</p><h3 id="_5-3-增量轮询" tabindex="-1"><a class="header-anchor" href="#_5-3-增量轮询" aria-hidden="true">#</a> 5.3 增量轮询</h3><p>看板不做 WebSocket 推送，用最朴素的轮询——900ms 一次，带 <code>since</code>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>GET /api/activity?since=123&amp;token=...
→ { now, seq, peers: [ { name, sessions: [ { id, status, events: [...] } ] } ] }
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>只返回 <code>seq &gt; since</code> 的事件，所以每次响应都很小。服务端对每个会话保留最近 400 条、全局 4000 条，超出就丢最久未活动会话的最旧事件。</p><p>选择轮询而不是 SSE 的原因很实际：看板通常只看一会儿，轮询的失败恢复（刷新页面、断网重连）几乎不需要写代码。</p><h3 id="_5-4-渲染" tabindex="-1"><a class="header-anchor" href="#_5-4-渲染" aria-hidden="true">#</a> 5.4 渲染</h3><p>页面是<strong>一个自包含的 HTML 字符串</strong>，没有外部资源、没有前端构建步骤——由一个函数直接返回：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">dashboardHtml</span><span class="token punctuation">(</span><span class="token parameter">token</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">&lt;!doctype html&gt;
  &lt;html&gt;…&lt;script&gt;
    let since = 0
    async function tick() {
      const r = await fetch(&#39;api/activity?since=&#39; + since + &#39;&amp;token=&#39; + encodeURIComponent(TOKEN))
      const data = await r.json()
      render(data)
      since = Math.max(since, data.seq)
    }
    setInterval(tick, 900)
  &lt;/script&gt;&lt;/html&gt;</span><span class="token template-punctuation string">\`</span></span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>渲染逻辑按&quot;会话&quot;分组，每个会话一个容器，新事件 append 到末尾；顶部是 peer 状态灯（有 running 会话就是绿点）。用户勾选&quot;跟随&quot;时自动滚到底部。</p><p>实际效果就是一条按时间排列的流水：紫色是 reasoning，黄色是工具调用，绿色是工具结果，红色是失败，灰色是回合边界。</p><h3 id="_5-5-安全" tabindex="-1"><a class="header-anchor" href="#_5-5-安全" aria-hidden="true">#</a> 5.5 安全</h3><p>看板跑在公网 3080 上，所以：</p><ul><li>页面和 JSON 接口都要 <code>token</code> 查询参数；</li><li>token 只在 URL 里出现，页面内部把它拼进 fetch；</li><li>桥只读、不提供任何写接口。</li></ul><h2 id="_6-真实联调" tabindex="-1"><a class="header-anchor" href="#_6-真实联调" aria-hidden="true">#</a> 6. 真实联调</h2><p>这套东西不是纸上设计，最后是在真机上跑通的：</p><ol><li>Windows 上 <code>dsh --profile sdk</code> 起 link，通过 <code>ws://…/dsh-peer</code> 连到 Linux 的 hub；</li><li>Linux 这边 <code>peer_ask(peer=&quot;HP&quot;, prompt=&quot;查磁盘&quot;)</code>，Windows 的 agent 用 pwsh 执行并返回结果；</li><li>让它用 <code>mini-program-automator</code> 连微信开发者工具，读页面元素、截图、把二维码和截图通过上传口传回来；</li><li>活动看板上能看到它每一步的 reasoning、工具调用和结果。</li></ol><p>踩过的坑也值得记一下：</p><ul><li><strong>web profile 的工具在 preset 里</strong>，全局只有 peer 自己的工具；</li><li><strong>0.2.0 没有 <code>session/resume</code></strong>，重连必须回退 <code>agents.resume</code>；</li><li><strong>HMR 只替换 profile 目录内的插件文件</strong>，树外的新文件不会热加载——所以桥才做成了独立进程；</li><li><strong>Windows 沙箱要求 temp 在工作区外</strong>，工作区在主目录时 <code>%LOCALAPPDATA%\\Temp</code> 正好落在里面，会直接拒绝启动；</li><li><strong>微信开发者工具 CLI 要写 <code>%LOCALAPPDATA%</code></strong>，工作区不在主目录时会被沙箱拦；还要在设置里手动打开&quot;服务端口&quot;，预览码必须用真实 AppID（<code>touristappid</code> 会报 <code>不存在此 AppID</code>）。</li></ul><h2 id="_7-限制与后续" tabindex="-1"><a class="header-anchor" href="#_7-限制与后续" aria-hidden="true">#</a> 7. 限制与后续</h2><ul><li>link 侧 agent 是事件驱动的：只在被 prompt 时运行，不能凭空主动开一轮；但可以在跑任务中 <code>peer_reply</code> 插话。</li><li>看板目前只覆盖经过桥的连接；直连 TCP 的 link 需要把同样的录制逻辑放进 hub。</li><li>如果是多人/多机，可能要给事件加订阅与权限（现在 token 是全有或全无）。</li><li>想做&quot;嵌进 dsh Web GUI 的面板&quot;，需要客户端插件 + typert 描述符，工作量明显更大，暂时保持独立页面。</li></ul><h2 id="_8-代码" tabindex="-1"><a class="header-anchor" href="#_8-代码" aria-hidden="true">#</a> 8. 代码</h2>`,91),m={href:"https://github.com/SparksDing/dsh-peer",target:"_blank",rel:"noopener noreferrer"},b=o("<li>后端：<code>lib/protocol.js</code>、<code>lib/hub.js</code>、<code>lib/link.js</code>、<code>lib/link-server.js</code></li><li>传输：<code>lib/transport.js</code>、<code>lib/ws.js</code></li><li>前端看板：<code>lib/activity.js</code>（事件模型 + HTML）、<code>bin/peer-ws-bridge.mjs</code>（旁路解析 + HTTP 端点）</li><li>测试：<code>node test/hub.test.mjs</code>、<code>node test/tools.test.mjs</code>（无需模型、无需 dsh）</li>",4),g=s("p",null,'如果这个思路对你有用，欢迎拿去改。也欢迎在 issue 里聊聊更好的观测方案——尤其是"怎么在不改被观测进程的前提下做事件旁路"这件事。',-1);function x(_,q){const a=t("ExternalLinkIcon"),p=t("RouterLink");return c(),d("div",null,[k,s("p",null,[n("代码在 "),s("a",v,[n("SparksDing/dsh-peer"),e(a)]),n('。这篇写清楚它是怎么设计的、交互长什么样，以及前端看板为什么做在"桥"上。')]),s("blockquote",null,[s("p",null,[n("English version: "),e(p,{to:"/en/architecture/dsh-peer.html"},{default:l(()=>[n("Let Two DeepSeek Harness Instances Talk Across Machines")]),_:1})])]),r(" more "),h,s("ul",null,[s("li",null,[n("仓库："),s("a",m,[n("SparksDing/dsh-peer"),e(a)])]),b]),g])}const f=i(u,[["render",x],["__file","dsh-peer.html.vue"]]);export{f as default};
